def _round(numerator, mode):
    if mode == "half_up":
        return (numerator + 5000) // 10000
    return numerator // 10000


def _ledger(data, priority, tax_base, refunds):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if priority == "sequence_first":
            key = (sequence, event.get("revision", 0), position)
        else:
            key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if tax_base == "discounted" else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        amount = net + tax
        if refunds and event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = {name: tuple(bounds) for name, bounds in data["roots"].items()}
    best = None
    best_vector = None

    def acyclic(edges):
        visiting, visited = set(), set()

        def visit(name):
            if name in visiting:
                return False
            if name in visited:
                return True
            visiting.add(name)
            for other in edges.get(name, ()):
                if not visit(other):
                    return False
            visiting.remove(name)
            visited.add(name)
            return True

        return all(visit(name) for name in edges)

    def active_deps(row):
        return [dep for dep in row.get("deps", [])
                if not dep.get("feature") or dep["feature"] in features]

    def search(chosen, limits, edges):
        nonlocal best, best_vector
        for name, version in chosen.items():
            if name not in limits or not (limits[name][0] <= version <= limits[name][1]):
                return

        pending = [name for name in limits if name not in chosen]
        if not pending:
            if not acyclic(edges):
                return
            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector, best = vector, dict(chosen)
            return

        name = max(pending)
        low, high = limits[name]
        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_limits = dict(limits)
            next_edges = dict(edges)
            deps = active_deps(row)
            next_edges[name] = [dep["name"] for dep in deps]
            valid = True
            for dep in deps:
                dep_name = dep["name"]
                low_dep, high_dep = dep["min"], dep["max"]
                if dep_name in next_limits:
                    old_low, old_high = next_limits[dep_name]
                    low_dep = max(low_dep, old_low)
                    high_dep = min(high_dep, old_high)
                if low_dep > high_dep:
                    valid = False
                    break
                next_limits[dep_name] = (low_dep, high_dep)
            if valid:
                search(next_chosen, next_limits, next_edges)

    search({}, roots, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _scheduler(data):
    from itertools import combinations

    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None

    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not (low <= counts.get(group, 0) <= high)
               for group, (low, high) in quotas.items()):
            continue
        if any(sum(job["start"] <= t < job["end"] for job in subset) > 2
               for t in {job["start"] for job in subset}):
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _routes(data):
    import heapq

    required = data.get("required", [])
    required_bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1

    def mark(mask, node):
        return mask | required_bit.get(node, 0)

    source = data["source"]
    initial = (source, mark(0, source), data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"],) + initial]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], remaining)]
            if remaining:
                durations.append((max(1, edge["duration"] - edge.get("discount", 0)),
                                  remaining - 1))
            next_node = edge["v"]
            next_mask = mark(mask, next_node)
            for duration, left in durations:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_state = (next_node, next_mask, left)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time,) + next_state)
    return {"arrival": None}


